const lessons=[
{slug:'case-construction',title:'Case construction',level:'Beginner',summary:'Build a logical, evidence-backed constructive from resolution to impact.',principle:'Claim → warrant → evidence → impact. Each link must actually follow from the one before it.',steps:['Define the resolution and your advocacy clearly.','Choose a framework that explains what the judge should value.','Write 2–3 distinct contentions; each needs a claim and causal reasoning.','Attach verifiable sources with author, date and original context.','End every contention with consequences and why they matter.'],exercise:'In 10 minutes, outline one contention on any resolution. Highlight the weakest causal link, then rewrite it.',pitfall:'A dramatic statistic is not a warrant; prove the causal connection.'},
{slug:'impact-calculus',title:'Impact calculus',level:'Beginner',summary:'Explain why your impacts outweigh theirs, not just that yours exist.',principle:'Compare magnitude, probability, timeframe, reversibility, and scope; then explain which comparison is decisive.',steps:['Identify your best and their best surviving impacts.','Compare at least two measurable dimensions.','Explain why your evidence makes that comparison credible.','Explicitly connect your weighing to the ballot.'],exercise:'Argue that a smaller but highly likely impact outweighs a larger speculative impact in 30 seconds.',pitfall:'Do not just say “our impact is bigger.” Show how and why.'},
{slug:'strategic-concession',title:'Strategic concession & collapse',level:'Intermediate',summary:'Win fewer arguments decisively instead of covering every minor point.',principle:'You may concede a low-stakes point if doing so protects a stronger voting issue—never concede an uncontested turn without a plan.',steps:['Map your own offense, their offense, and shared assumptions.','Separate decisive arguments from secondary claims.','Concede only points that do not destroy your core path to a ballot.','Collapse in summary and maintain the same story in final focus.'],exercise:'Given three live arguments, pick one to drop and explain the tradeoff.',pitfall:'Never accidentally concede a premise that becomes a gateway to their main offense.'},
{slug:'turns',title:'Turns & avoiding double turns',level:'Intermediate',summary:'Turn an opponent’s claim into offense without arguing both directions by accident.',principle:'A link turn denies the causal direction; an impact turn says the claimed outcome is good. Using both against the same link chain can double-turn you.',steps:['Write the opponent’s claim as A → B → harm.','Try a link turn: A actually prevents B.','Try an impact turn: B would actually be beneficial.','Choose a consistent strategy; do not combine contradictory turns.'],exercise:'Opponent says regulation raises prices. Build one clean link turn, then separately build one impact turn.',pitfall:'Stacking incompatible answers gives the opponent a route to your own offense.'},
{slug:'evidence-comparison',title:'Evidence comparison',level:'Beginner',summary:'Make evidence quality an argument, not an afterthought.',principle:'Compare authorship, methods, recency, context, source bias and direct applicability.',steps:['Read the original source, not just the cut card.','Find the data source, sample and limitations.','Contrast competing studies by what they actually measure.','Tell the judge which evidence better predicts the resolution’s world.'],exercise:'Compare a recent study of 300 sites with an older expert essay. Explain limits of both without pretending one always wins.',pitfall:'Recency alone does not prove a source is more reliable.'},
{slug:'judge-adaptation',title:'Judge adaptation',level:'Beginner',summary:'Keep the rigor, change how you communicate it.',principle:'For lay judges: define jargon, narrate the clash and slow down; for technical judges: precise comparison and extension.',steps:['Identify the likely judging paradigm before the round.','Use plain-language tags and explain abbreviations.','Signpost the two or three reasons to vote for you.','Watch for confusion and restate causal claims simply.'],exercise:'Translate a dense 20-second technical extension for a parent judge.',pitfall:'Being persuasive does not justify stretching evidence or misrepresenting the record.'},
{slug:'ballot-writing',title:'Ballot writing',level:'Intermediate',summary:'Give the judge a clear reason for decision before they have to invent one.',principle:'A ballot story explains the decisive clash, why you win it, and why it outweighs competing offense.',steps:['Identify the most important clash in the round.','Summarize what both teams proved, fairly.','Explain the comparative voting issue with the best evidence.','Write a 3-sentence hypothetical judge RFD.'],exercise:'After a practice round, write the judge’s ballot for both sides in no more than five sentences each.',pitfall:'Do not confuse speaking better with winning the substantive clash.'},
{slug:'speech-crystallization',title:'Summary & final focus',level:'Intermediate',summary:'Carry a coherent winning story through the last two speeches.',principle:'Final focus should crystallize the decisive offense that was properly extended; it is not a chance to introduce a new case.',steps:['In summary, extend the warranted offense and answer the key defense.','Include explicit weighing against the opponent’s best offense.','In final focus, narrow to one or two voting issues.','Tell the judge what the ballot should say.'],exercise:'Turn a four-point rebuttal into a 45-second summary and then a 20-second final focus.',pitfall:'Do not suddenly introduce a brand-new voting issue at the end.'}
];
