async function api(path,method='GET',data=null){
 const headers={};const opts={method,credentials:'same-origin',headers};
 if(me&&method!=='GET')headers['X-CSRF-Token']=me.csrf;
 if(data instanceof FormData){opts.body=data;}else if(data!==null){headers['Content-Type']='application/json';opts.body=JSON.stringify(data);}
 let res;
 try{res=await fetch(path,opts);}catch(e){throw new Error('Could not connect to the server.');}
 let out={};try{out=await res.json();}catch{}
 if(!res.ok){if(res.status===401&&path!=='/api/login'){me=null;state=null;loginView();}throw new Error(out.detail||'Request failed.');}
 return out;
}
async function refresh(){state=await api('/api/state'); render();}
function toast(message,error=false){const root=$('#toast-root'),el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;root.appendChild(el);setTimeout(()=>el.remove(),4600);}
const run=async(fn,success='Saved')=>{try{await fn();if(success)toast(success);await refresh();}catch(e){toast(e.message,true);}};

