function tournamentsView(){
 const month=new Date(today.getFullYear(),today.getMonth()+calendarOffset,1);
 const yr=month.getFullYear(),mo=month.getMonth();
 const leading=(month.getDay()+6)%7;
 const days=new Date(yr,mo+1,0).getDate();
 const cal=[...Array.from({length:leading},()=>'<div class="cal-day empty-day"></div>'),...Array.from({length:days},(_,i)=>{const date=dateOnly(new Date(yr,mo,i+1));const ev=state.tournaments.filter(t=>t.event_date===date);return `<div class="cal-day ${date===dateOnly(new Date())?'today':''} ${ev.length?'has-event':''}" ${ev.length?`data-event-date="${date}"`:''}><div class="day-num">${i+1}</div>${ev.slice(0,2).map(t=>`<span class="cal-event" title="${attr(t.title)}">${truncated(t.title,24)}</span>`).join('')}</div>`;})].join('');
 const events=state.tournaments;
 return `${head('COMPETITION SEASON','Tournament calendar','Keep track of competitions, logistics, and preparation deadlines.',isAdmin()?btn(`${icon('plus')} Add tournament`,'tournament-new',''):'')}
 <div class="grid-main"><section class="panel"><div class="panel-header"><div><h2>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><p>Select an event day to see its details</p></div><div class="row">${btn(icon('back'),'cal-prev','secondary small')}${btn('Today','cal-today','secondary small')}${btn(icon('right'),'cal-next','secondary small')}</div></div><div class="cal-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="cal-weekday">${d}</div>`).join('')}${cal}</div></section><aside class="panel"><div class="panel-header"><div><h2>Upcoming tournaments</h2><p>All scheduled competitions</p></div></div>${events.length?events.map(e=>`<div class="event-card"><div class="event-date"><small>${new Date(e.event_date+'T12:00:00').toLocaleString('en-US',{month:'short'}).toUpperCase()}</small><strong>${e.event_date.slice(-2)}</strong></div><div style="flex:1;min-width:0"><h3>${esc(e.title)}</h3><div class="muted" style="font-size:11px">${e.event_time?esc(e.event_time)+' · ':''}${e.location?esc(e.location):'Location TBD'}</div>${e.details?`<p style="margin:9px 0;font-size:12px;color:#8290a2">${truncated(e.details,145)}</p>`:''}<div class="row" style="margin-top:10px">${e.link?`<a class="link-btn" href="${attr(e.link)}" target="_blank" rel="noopener noreferrer">Info ${icon('arrow',12)}</a>`:''}${isAdmin()?btn(icon('trash'),'tournament-delete','danger tiny',e.id):''}</div></div></div>`).join(''):noItems('No events yet','Tournament dates will appear here.','trophy')}</aside></div>`;
}
