 const options=state.tasks.filter(t=>isAdmin()||getAssignment(t.id,me.id)).map(t=>[t.id,t.title]);
 const form=`${field('Submission title','title','',{required:true,placeholder:'e.g. Rebuttal recording — November practice'})}${selection('Related assignment (optional)','task_id',[['','Independent practice'],...options],taskId)}${area('Notes for Max','notes','','What should leadership review?')}${field('Link to Google Doc / video / recording','url','',{type:'url',placeholder:'https://...',hint:'Use a link or attach a file below (or both).'})}<div class="form-group"><label class="label">Attach a file</label><input class="field" type="file" name="attachment" accept=".pdf,.doc,.docx,.txt,.rtf,.ppt,.pptx,.xls,.xlsx,.csv,.png,.jpg,.jpeg,.gif,.webp,.mp4,.mov,.webm,.mp3,.m4a,.wav"><p class="hint">PDFs, documents, images, audio, and video · up to 50 MB. Large videos can be linked instead.</p></div>`;
 openModal('Submit work',form,async f=>{if(!f.get('url')&&!f.get('attachment')?.size){toast('Add a file or link.',true);return false;}await api('/api/submissions','POST',f);},{submit:'Send submission'});
