function showResourceForm(){openModal('Add a resource',`${field('Title','title','',{required:true})}${selection('Category','category',[['Guide','Guide'],['Template','Template'],['Evidence','Evidence'],['Video','Video'],['Article','Article'],['Other','Other']])}${field('Short description','description')}${field('Link (optional)','url','',{type:'url',placeholder:'https://...'})}${area('Content or instructions (optional)','body')}`,async f=>{await api('/api/resources','POST',formJSON(f));},{submit:'Publish resource'});}
function showTournamentForm(){openModal('Add tournament',`${field('Tournament name','title','',{required:true,placeholder:'e.g. Winter Invitational'})}<div class="form-row">${field('Date','event_date','',{type:'date',required:true})}${field('Time / check-in','event_time','',{placeholder:'e.g. 8:30 AM'})}</div>${field('Location','location','',{placeholder:'School, city, or TBD'})}${field('Registration / info URL','link','',{type:'url',placeholder:'https://tabroom.com/...'})}${area('Details','details','','Notes about schedule, travel, registration, partner prep.')}`,async f=>{await api('/api/tournaments','POST',formJSON(f));},{submit:'Add to calendar'});}
function showPasswordChange(){openModal('Change my password',`${field('Current password','current','',{type:'password',required:true})}${field('New password','password','',{type:'password',required:true,min:10,hint:'At least 10 characters. Use a unique password or passphrase.'})}${field('Confirm new password','confirm','',{type:'password',required:true})}`,async f=>{if(f.get('password')!==f.get('confirm')){toast('New passwords do not match.',true);return false;}await api('/api/password','POST',{current:f.get('current'),password:f.get('password')});},{submit:'Update password'});}
function showSubmissionReview(s){openModal('Review · '+s.title,`<p class="muted">Submitted by <b>${esc(mName(s.user_id))}</b> · ${fmtDate(s.created_at.slice(0,10))}</p>${s.notes?`<div class="card-soft" style="white-space:pre-wrap;margin-bottom:18px">${esc(s.notes)}</div>`:''}<div class="row" style="margin:0 0 20px">${s.stored_name?`<a class="btn secondary small" href="/api/submissions/${s.id}/download">${icon('download')} Download file</a>`:''}${s.url?`<a class="btn secondary small" href="${attr(s.url)}" target="_blank" rel="noopener noreferrer">${icon('arrow')} Open link</a>`:''}</div>${selection('Review result','status',[['new','Awaiting review'],['reviewed','Reviewed'],['revision_requested','Request revision']],s.status)}${area('Feedback to member','feedback',s.feedback||'','Specific notes, strengths, or requested changes')}`,async f=>{await api(`/api/submissions/${s.id}`,'PATCH',formJSON(f));},{submit:'Send feedback'});}
function showSubmissionFeedback(s){openModal('Feedback · '+s.title,`<div class="row" style="margin-bottom:18px">${statusPill(s.status)}<span class="muted">${fmtDate(s.created_at.slice(0,10))}</span></div><div class="card-soft" style="white-space:pre-wrap">${esc(s.feedback||'No feedback yet.')}</div>`);}
function showCaseView(c){openModal(c.title,`<div class="row" style="margin-bottom:17px">${catPill(c.side)}${catPill(c.category)}${statusPill(c.status)}</div><div class="label">Argument and evidence</div><div style="white-space:pre-wrap;line-height:1.8;color:#5e697c">${esc(c.argument||'No argument text yet.')}</div><hr class="section-divider"><div class="row-between" style="flex-wrap:wrap"><span class="muted" style="font-size:12px">Added by ${esc(mName(c.created_by))}</span>${c.source_url?`<a href="${attr(c.source_url)}" target="_blank" rel="noopener noreferrer" class="btn ghost small">Original source ${icon('arrow',13)}</a>`:''}</div>${isAdmin()||c.created_by===me.id?`<div class="row" style="margin-top:20px">${btn('Edit argument','case-edit','secondary small',c.id)}${btn('Delete','case-delete','danger small',c.id)}</div>`:''}`,null,{wide:true});}
async function makeTempCredentials(m){const res=await api(`/api/members/${m.id}/reset-password`,'POST');await refresh();credentialsModal(m.username,res.temporary_password);}
function clockStr(n){return `${two(Math.floor(n/60))}:${two(n%60)}`;}
function timerStop(){timer.running=false;timer.endAt=0;if(timer.interval){clearInterval(timer.interval);timer.interval=null;}}
function timerDuration(){return timer.kind==='round'?speechSteps[timer.step][1]:durPresets[timer.kind]||60;}
function timerReset(){timerStop();timer.remaining=timerDuration();updateTimerUI();}
function timerTick(){if(!timer.running)return;timer.remaining=Math.max(0,Math.ceil((timer.endAt-Date.now())/1000));if(timer.remaining===0){timerStop();toast('Time! Move to the next speech.');}updateTimerUI();}
function timerToggle(){if(timer.running){timerTick();timerStop();}else{if(timer.remaining===0)timer.remaining=timerDuration();timer.running=true;timer.endAt=Date.now()+timer.remaining*1000;timer.interval=setInterval(timerTick,200);}updateTimerUI();}
function timerNext(){timerStop();timer.step=timer.kind==='round'?Math.min(timer.step+1,speechSteps.length-1):0;timer.remaining=timerDuration();render();}
function updateTimerUI(){const clock=$('#timer-clock');if(clock)clock.textContent=clockStr(timer.remaining);const label=$('#timer-step-name');if(label)label.textContent=timer.kind==='round'?speechSteps[timer.step][0]:(timer.kind==='prep'?'Team prep':timer.kind.charAt(0).toUpperCase()+timer.kind.slice(1)+' drill');const btntext=$('#timer-play-text');if(btntext)btntext.textContent=timer.running?'Pause':'Start';}

// All interactions are delegated, including content that was dynamically rendered.
document.addEventListener('click',async event=>{
 const nav=event.target.closest('[data-page]');if(nav){go(nav.dataset.page);return;}
 const day=event.target.closest('[data-event-date]');if(day){const ev=state.tournaments.filter(e=>e.event_date===day.dataset.eventDate);openModal(fmtDate(day.dataset.eventDate),ev.map(e=>`<div class="card-soft" style="margin-bottom:12px"><h3>${esc(e.title)}</h3><p class="muted">${esc(e.event_time||'Time TBD')} · ${esc(e.location||'Location TBD')}</p><p style="white-space:pre-wrap">${esc(e.details||'No details yet.')}</p></div>`).join(''));return;}
 const node=event.target.closest('[data-action]');if(!node)return;
 const action=node.dataset.action,id=node.dataset.id;
 try{
 switch(action){
 case'menu':$('#sidebar')?.classList.toggle('open');break;
 case'logout':await api('/api/logout','POST');me=null;state=null;loginView();break;
 case'modal-close':closeModal();break;
 case'go-tournaments':go('tournaments');break;
 case'go-training':go('training');break;
 case'go-schedule':go('schedule');break;
 case'go-practice':go('practice');break;
 case'task-new':showTaskForm();break;
 case'task-edit':showTaskForm(state.tasks.find(t=>t.id===Number(id)));break;
 case'task-delete':if(confirm('Delete this assignment for everyone? This cannot be undone.'))await run(()=>api(`/api/tasks/${id}`,'DELETE'),'Assignment deleted');break;
 case'task-filter':activeTaskFilter=id;render();break;
 case'submission-new':showSubmissionForm(id||'');break;
 case'submission-review':showSubmissionReview(state.submissions.find(s=>s.id===Number(id)));break;
 case'submission-feedback':showSubmissionFeedback(state.submissions.find(s=>s.id===Number(id)));break;
 case'schedule-mine':scheduleMode='mine';render();break;
 case'toggle-slot':{const k=slotKey(Number(node.dataset.day),Number(node.dataset.hour));if(selectedSlots.has(k))selectedSlots.delete(k);else selectedSlots.add(k);render();break;}
 case'save-availability':await run(()=>api('/api/availability','PUT',{slots:[...selectedSlots].map(k=>k.split('-').map(Number))}),'Availability shared with your team');break;
 case'lesson-filter':lessonFilter=id;render();break;
 case'lesson-open':lessonModal(id);break;
 case'drill-random':currentPrompt=(currentPrompt+1+Math.floor(Math.random()*5));render();break;
 case'topic-random':{drillCounter++;const i=(currentPrompt+drillCounter)%topics.length;const topic=$('#generated-topic');if(topic)topic.textContent=topics[i];break;}
 case'argument-generate':{const a=rebuttalArgs[(drillCounter++ +currentPrompt)%rebuttalArgs.length];$('#argument-result').innerHTML=`<div class="card-soft"><div class="eyebrow">ARGUMENT TO TEST · NOT VERIFIED</div><b>${esc(a.claim)}</b><p class="muted" style="font-size:12px;margin:9px 0">Warrant to scrutinize: ${esc(a.warrant)}</p><p class="muted" style="font-size:12px;margin:0">Proposed impact: ${esc(a.impact)}</p></div>`;break;}
 case'timer-toggle':timerToggle();render();break;
 case'timer-reset':timerReset();render();break;
 case'timer-next':timerNext();break;
 case'timer-step':timerStop();timer.step=Number(id);timer.remaining=timerDuration();render();break;
 case'case-new':showCaseForm();break;
 case'case-edit':showCaseForm(state.cases.find(c=>c.id===Number(id)));break;
 case'case-view':showCaseView(state.cases.find(c=>c.id===Number(id)));break;
 case'case-delete':if(confirm('Permanently delete this argument?')){closeModal();await run(()=>api(`/api/cases/${id}`,'DELETE'),'Argument removed');}break;
 case'case-filter':caseFilter=id;render();break;
 case'mistake-new':showMistakeForm();break;
 case'mistake-practicing':case'mistake-resolved':case'mistake-open':{const status=action.split('-')[1];await run(()=>api(`/api/mistakes/${id}`,'PATCH',{status}),'Review status updated');break;}
 case'announcement-new':showAnnouncementForm();break;
 case'announcement-delete':if(confirm('Delete this announcement?'))await run(()=>api(`/api/announcements/${id}`,'DELETE'),'Announcement removed');break;
 case'resource-new':showResourceForm();break;
 case'resource-view':{const r=state.resources.find(r=>r.id===Number(id));openModal(r.title,`<span class="pill purple">${esc(r.category)}</span><p class="muted" style="margin:16px 0">${esc(r.description)}</p><div style="white-space:pre-wrap;line-height:1.75">${esc(r.body||'No detailed notes added.')}</div>`);break;}
 case'resource-delete':if(confirm('Delete this resource?'))await run(()=>api(`/api/resources/${id}`,'DELETE'),'Resource removed');break;
 case'resource-filter':resourceFilter=id;render();break;
 case'tournament-new':showTournamentForm();break;
 case'tournament-delete':if(confirm('Remove this tournament?'))await run(()=>api(`/api/tournaments/${id}`,'DELETE'),'Tournament removed');break;
 case'cal-prev':calendarOffset--;render();break;
 case'cal-next':calendarOffset++;render();break;
 case'cal-today':calendarOffset=0;render();break;
 case'feedback-new':showFeedbackForm();break;
 case'member-new':showMemberForm();break;
 case'member-edit':showMemberForm(state.members.find(m=>m.id===Number(id)));break;
 case'member-password':{const m=state.members.find(m=>m.id===Number(id));if(confirm(`Generate a ${m.has_password?'new':'first'} password for ${m.name}? ${m.has_password?'Their current password and sessions will stop working.':''}`))await makeTempCredentials(m);break;}
 case'password-bulk':{const missing=state.members.filter(m=>m.active&&!m.has_password);if(!missing.length){toast('Everyone already has a password.');break;}if(!confirm(`Generate first-time passwords for ${missing.length} members? You will need to share them privately.`))break;const result=[];for(const m of missing){const r=await api(`/api/members/${m.id}/reset-password`,'POST');result.push(`${m.name} (${m.username}): ${r.temporary_password}`);}await refresh();openModal('New member logins',`<p class="muted">Copy these credentials securely. They will not be shown again.</p><textarea class="field" rows="${Math.min(12,result.length+2)}" readonly id="bulk-passwords">${esc(result.join('\n'))}</textarea><div style="margin-top:12px">${btn(`${icon('copy')} Copy all`,'copy-bulk','secondary')}</div>`);break;}
 case'copy-bulk':await navigator.clipboard.writeText($('#bulk-passwords').value);toast('Copied securely.');break;
 case'copy-creds':await navigator.clipboard.writeText(`Username: ${node.dataset.username}\nPassword: ${node.dataset.password}`);toast('Credentials copied.');break;
 case'member-filter':roleFilter=id;render();break;
 case'change-password':showPasswordChange();break;
 case'select-all-assignees':$$('#active-modal-form input[name="assignees"]').forEach(el=>el.checked=true);break;
 default:break;
 }
 }catch(e){toast(e.message,true);}
});
document.addEventListener('change',async event=>{
 const t=event.target;
 try{
 if(t.id==='schedule-mode'){scheduleMode=t.value;if(scheduleMode==='person'&&(!schedulePerson||schedulePerson==='team'))schedulePerson=members()[0]?.id;render();}
 else if(t.id==='schedule-person'){schedulePerson=t.value;render();}
 else if(t.id==='review-member'){reviewMember=t.value;render();}
 else if(t.id==='drill-type'){currentDrill=t.value;currentPrompt=0;render();}
 else if(t.id==='timer-kind'){timerStop();timer.kind=t.value;timer.step=0;timer.remaining=timerDuration();render();}
 else if(t.dataset.taskstatus){const tid=Number(t.dataset.taskstatus);await run(()=>api(`/api/tasks/${tid}/status`,'PATCH',{status:t.value}),'Assignment status updated');}
 }catch(e){toast(e.message,true);}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length)closeModal();});
document.addEventListener('click',e=>{if(e.target.id==='modal-cover')closeModal();});
(async()=>{try{me=await api('/api/me');await refresh();}catch(e){loginView();}})();
